"use client";
import { useState, type FormEvent } from "react";
import { useParams, useRouter } from "next/navigation";
import Image from "@/components/courses/CourseImage";
import Link from "next/link";
import { Plus, Trash2, Save, ArrowLeft } from "lucide-react";
import { useLearnova } from "@/components/LearnovaProvider";
import { EmptyState, LoadingCards, PageHeader } from "@/components/ui";
import { categories, levels, categoryImages, makeLessons, type Category, type Course, type Lesson, type Level } from "@/data/courses";
export default function CourseEditor({ edit = false }: { edit?: boolean }) {
  const { id } = useParams<{ id: string }>(); const { state } = useLearnova();
  if (!state.ready) return <LoadingCards />;
  const course = edit ? state.courses.find(c => c.id === id) : undefined;
  if (edit && !course) return <EmptyState title="Course not found" description="The course may have been removed." href="/instructor-dashboard/courses" action="My Courses" />;
  return <CourseForm key={course?.id ?? "new"} course={course} />;
}
function CourseForm({ course }: { course?: Course }) {
  const { state, user, dispatch } = useLearnova(); const router = useRouter();
  const [title, setTitle] = useState(course?.title ?? ""); const [description, setDescription] = useState(course?.description ?? "");
  const [category, setCategory] = useState<Category>(course?.category ?? "Programming"); const [level, setLevel] = useState<Level>(course?.level ?? "Beginner");
  const [duration, setDuration] = useState(course?.duration ?? "6 weeks"); const [price, setPrice] = useState(String(course?.price ?? 0));
  const [image, setImage] = useState(course?.image ?? categoryImages.Programming); const [outcomes, setOutcomes] = useState(course?.outcomes.join("\n") ?? "");
  const [lessons, setLessons] = useState<Lesson[]>(course?.lessons ?? makeLessons(["Introduction", "Core Concepts", "Practical Project"], "Your Course")); const [error, setError] = useState("");
  function updateLesson(index: number, field: keyof Lesson, value: string) { setLessons(lessons.map((l, i) => i === index ? { ...l, [field]: value } : l)); }
  async function submit(e: FormEvent) {
    e.preventDefault(); const outcomeList = outcomes.split("\n").map(s => s.trim()).filter(Boolean); const amount = Number(price);
    if (title.trim().length < 3 || description.trim().length < 20 || !duration.trim() || !outcomeList.length || !lessons.length || lessons.some(l => !l.title.trim() || !l.content.trim() || !l.duration.trim()) || price.trim() === "" || !Number.isFinite(amount) || amount < 0) { setError("Add a title, description (20+ characters), duration, at least one learning outcome and complete lesson. Price must be zero or greater."); return; }
    const instructor = user && ["instructor", "admin"].includes(user.role) ? user : state.users.find(u => u.id === "instructor-1") ?? state.users.find(u => u.role === "instructor");
    if (!instructor) { setError("Create an instructor account before creating a course."); return; }
    const saved: Course = { id: course?.id ?? crypto.randomUUID(), title: title.trim(), description: description.trim(), category, level, duration: duration.trim(), price: amount, image, outcomes: outcomeList, lessons: lessons.map(l => ({ ...l, title: l.title.trim(), content: l.content.trim() })), instructor: course?.instructor ?? instructor.name, instructorId: course?.instructorId ?? instructor.id, rating: course?.rating ?? 0, students: course?.students ?? 0, quiz: course?.quiz, assignment: course?.assignment };
    if (!(await dispatch({ type: "save-course", course: saved })).ok) return; router.push("/instructor-dashboard/courses");
  }
  return <><Link href="/instructor-dashboard/courses" className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-blue-400"><ArrowLeft size={16} />My Courses</Link><PageHeader title={course ? "Edit Course" : "Create Course"} description="Give your learners a clear path from the first lesson to a practical project." /><form onSubmit={submit} className="space-y-6" noValidate>
    <section className="panel grid gap-5 p-6 sm:grid-cols-2"><label className="sm:col-span-2"><span className="field-label">Course Title</span><input className="field" value={title} onChange={e => setTitle(e.target.value)} /></label><label className="sm:col-span-2"><span className="field-label">Description</span><textarea className="field min-h-32" value={description} onChange={e => setDescription(e.target.value)} /></label><label><span className="field-label">Category</span><select className="field" value={category} onChange={e => { const value = e.target.value as Category; setCategory(value); if (!image.startsWith("data:")) setImage(categoryImages[value]); }}>{categories.map(c => <option key={c}>{c}</option>)}</select></label><label><span className="field-label">Level</span><select className="field" value={level} onChange={e => setLevel(e.target.value as Level)}>{levels.map(l => <option key={l}>{l}</option>)}</select></label><label><span className="field-label">Duration</span><input className="field" value={duration} onChange={e => setDuration(e.target.value)} placeholder="6 weeks" /></label><label><span className="field-label">Price (USD)</span><input className="field" type="number" min="0" step="0.01" value={price} onChange={e => setPrice(e.target.value)} /></label><label className="sm:col-span-2"><span className="field-label">Learning Outcomes — one per line</span><textarea className="field min-h-28" value={outcomes} onChange={e => setOutcomes(e.target.value)} /></label><div className="sm:col-span-2"><label className="field-label" htmlFor="thumbnail">Thumbnail</label><div className="flex flex-wrap items-center gap-5"><div className="relative h-28 w-44 rounded-xl bg-blue-500/10"><Image src={image} alt="Course thumbnail preview" fill unoptimized={image.startsWith("data:")} className="object-contain p-2" sizes="176px" /></div><div><input id="thumbnail" type="file" accept="image/png,image/jpeg,image/webp" className="max-w-full text-sm" onChange={e => { const file = e.target.files?.[0]; if (!file) return; if (!["image/png", "image/jpeg", "image/webp"].includes(file.type) || file.size > 500 * 1024) { setError("Choose a PNG, JPEG or WebP thumbnail under 500 KB."); return; } const reader = new FileReader(); reader.onload = () => { setImage(String(reader.result)); setError(""); }; reader.readAsDataURL(file); }} /><p className="mt-2 text-xs text-slate-400">PNG, JPEG or WebP · Up to 500 KB · Saved with your course</p><button type="button" className="mt-3 text-xs font-semibold text-blue-400" onClick={() => setImage(categoryImages[category])}>Use category image</button></div></div></div></section>
    <section className="panel p-6"><div className="flex items-center justify-between gap-3"><h2 className="section-title">Lessons</h2><button type="button" className="btn-secondary" onClick={() => setLessons([...lessons, { id: crypto.randomUUID(), title: "", duration: "20 min", content: "", exercise: "" }])}><Plus size={16} />Add Lesson</button></div><div className="mt-5 space-y-5">{lessons.map((lesson, index) => <fieldset key={lesson.id} className="rounded-xl border border-white/10 p-4"><legend className="px-2 text-sm font-bold">Lesson {index + 1}</legend><div className="grid gap-4 sm:grid-cols-2"><label><span className="field-label">Lesson title</span><input className="field" value={lesson.title} onChange={e => updateLesson(index, "title", e.target.value)} /></label><label><span className="field-label">Duration</span><input className="field" value={lesson.duration} onChange={e => updateLesson(index, "duration", e.target.value)} /></label><label className="sm:col-span-2"><span className="field-label">Lesson content</span><textarea className="field min-h-28" value={lesson.content} onChange={e => updateLesson(index, "content", e.target.value)} /></label><label className="sm:col-span-2"><span className="field-label">Practice exercise</span><textarea className="field" value={lesson.exercise} onChange={e => updateLesson(index, "exercise", e.target.value)} /></label></div><button type="button" className="mt-4 inline-flex items-center gap-2 text-sm text-red-500" onClick={() => setLessons(lessons.filter((_, i) => i !== index))}><Trash2 size={15} />Remove Lesson</button></fieldset>)}</div></section>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="flex flex-wrap gap-3"><button className="btn-primary"><Save size={17} />{course ? "Save Changes" : "Create Course"}</button><Link className="btn-secondary" href="/instructor-dashboard/courses">Cancel</Link></div>
  </form></>;
}
